public void populate(FMCustomer _customerTable, FMAddressTable _addressTable)
{
    this.customerFullName(_customerTable.fullName());
    this.customerFirstName(_customerTable.FirstName);
    this.customerLastName(_customerTable.LastName);
    this.driverLicenseNumber(_customerTable.DriverLicense);
    this.customerEmail(_customerTable.Email);
    this.customerPhone(_customerTable.CellPhone);

    this.customerAddress(_addressTable.FullAddress());

    if (_customerTable.Image != conNull())
    {
        Image img = new Image();
        img.setData(_customerTable.Image);
        this.customerImage(ImageReference::constructForImage(img));
    }

    if (_customerTable.LicenseImage != conNull())
    {
        Image licenseImg = new Image();
        licenseImg.setData(_customerTable.LicenseImage);
        this.licenseImage(ImageReference::constructForImage(licenseImg));
    }

    this.RecId(_customerTable.RecId);
}

public static FMCustomerDetailsPage getCustomerDetails(SysAppEntityContext _entityContext, List _filterContextList)
{
    if (_entityContext && _entityContext.entityId())
    {
        int64 canonicalId = str2Int64(_entityContext.entityId());
        FMCustomer customerTable;
        FMAddressTable addressTable;

        select firstonly * from customerTable
            join addressTable
            where customerTable.RecId == canonicalId
            && addressTable.RecId == customerTable.AddressID;

        FMCustomerDetailsPage customerDetailsPage = new FMCustomerDetailsPage();
        customerDetailsPage.populate(customerTable, addressTable);
        return customerDetailsPage;
    }
    else
    {
        return null;
    }
}
